import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { Dropdown } from 'carbon-components-react';
import Warning16 from '@carbon/icons-react/lib/warning/16';
import Checkmark16 from '@carbon/icons-react/lib/checkmark/16';
import Add16 from '@carbon/icons-react/lib/add/16';

const iconItems = [
  { id: 'warning', label: 'Warning', icon: Warning16 },
  { id: 'checkmark', label: 'Checkmark', icon: Checkmark16 },
  { id: 'add', label: 'Add', icon: Add16 },
];

function App() {
  const [selectedItem, setSelectedItem] = React.useState(iconItems[0]);

  return (
    <div style={{ width: '200px', margin: '2rem' }}>
      <Dropdown
        id="icon-dropdown"
        items={iconItems}
        selectedItem={selectedItem}
        onChange={({ selectedItem }) => setSelectedItem(selectedItem)}
        // We’re returning the full object here, so it will toString to [object Object]
        itemToString={(item) => item}
        // We return our icon component for the menu options
        itemToElement={(item) => (item ? <item.icon /> : null)}
        label="Choose an icon"
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
